import{_ as t,H as s,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"05 | 超越FunctionCall：MCP为何更胜一筹？","description":"","frontmatter":{},"headers":[{"level":2,"title":"MCP 是什么？","slug":"mcp-是什么","link":"#mcp-是什么","children":[]},{"level":2,"title":"Function Call 和 MCP","slug":"function-call-和-mcp","link":"#function-call-和-mcp","children":[]},{"level":2,"title":"MCP 的第一个例子","slug":"mcp-的第一个例子","link":"#mcp-的第一个例子","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI重塑测试开发系统实践/05｜超越FunctionCall：MCP为何更胜一筹？.md","filePath":"AI重塑测试开发系统实践/05｜超越FunctionCall：MCP为何更胜一筹？.md","lastUpdated":1795562968000}'),n={name:"AI重塑测试开发系统实践/05｜超越FunctionCall：MCP为何更胜一筹？.md"};function l(p,e,o,E,r,h){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="_05-超越functioncall-mcp为何更胜一筹" tabindex="-1">05 | 超越FunctionCall：MCP为何更胜一筹？ <a class="header-anchor" href="#_05-超越functioncall-mcp为何更胜一筹" aria-label="Permalink to &quot;05 | 超越FunctionCall：MCP为何更胜一筹？&quot;">​</a></h1><p>你好，我是陈磊。</p><p>上一次我们一起聊了聊 RAG 系统相关的技术内容，其核心流程是将用户查询经 Embedding模型向量化后，在向量数据库中检索相似文档块（chunks），再与原查询组合输入大模型生成响应，从而减少幻觉并提升准确性。今天我们一起聊一聊 Anthropic 公司在 2024 年 1 月份推出的 MCP 协议，MCP（Model Context Protocol）协议一经推出就受到了大模型应用开发者的热捧，这既得益于实现 MCP 协议的简单，也得益于大模型本身存在的弊端。</p><h2 id="mcp-是什么" tabindex="-1">MCP 是什么？ <a class="header-anchor" href="#mcp-是什么" aria-label="Permalink to &quot;MCP 是什么？&quot;">​</a></h2><p>虽然大模型的能力非常强大，但是你也肯定听说过大模型最大的两个问题，一是知识在训练时期固定，二是无法与外部世界交互。</p><p>为什么说知识在训练时期固定呢？大模型在训练过程中基于特定数据集学习知识，这些数据集有明确的“截止日期”，GPT-3.5 Turbo 训练数据截止到 2021 年 9 月。训练完成后，模型无法自动更新或“学习”新信息，除非通过重新训练或微调。这就导致大模型对于训练数据截止日期以后的事情一无所知。</p><p>而且纯大模型本质上就是一个“封闭系统”，它们只能基于内部参数生成响应，无法直接调用API、访问数据库或执行实际操作（如预订会议、更新 CRM 记录）。 这意味着它们缺乏“代理能力”（agency），不能主动改变外部环境，大模型自己无法实时处理数据，也无法执行需要权限或者状态变化的任务。</p><p>MCP 的提出为大模型与外部数据、应用和服务之间建立了桥梁，它提供了一种安全、标准化的通信方式，将静态的大模型变成了动态的智能体，因此也可以用来解决大模型最大的两个问题。</p><p>MCP 建立在工具使用和函数调用等现有概念之上，并对其进行标准化。这样就无需为每个新的 AI 模型和外部系统创建自定义连接。它使 LLM 能够使用最新的真实数据、执行操作，并访问其原始训练中未包含的专业功能。因此 MCP 也给测试开发工程师提供了新思路。</p><p>测试开发工程师很难获得足够的时间、成本、算力投入到模型训练去，从零训练一个服务于测试的大模型这样的事情看机遇，那么微调一个服务于测试的模型也需要投入人力、算力、时间，这类业务需要团队提供强有力的支持，并不是每一个测试开发工程师都有的机遇。但是为大模型提供 MCP Server，让大模型可以访问我们的测试服务、测试数据，确实一个小成本的事情，只要掌握了 MCP 的开发，就可以实现了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/1.png" alt=""></a></p><p>MCP 就像一个“中介管家”，它能把各种本地或远程的资源和服务（比如数据、工具、API）连接起来，让它们通过统一的协议“聊天”，最终服务于一些 MCP Host 应用。想象一下：你家有本地资源（A 和 B），外面还有云端服务（C），MCP 就像快递中转站，把这些东西打包，通过专线（协议）送到你的“智能管家”App（MCP Host）手里。</p><p>整个流程是双向的：资源发数据给主机，主机也能控制资源。就如上图中所示，MCP 有三个组件 MCP Servers、MCP Protocol 和 MCP Host。下面我一步一步地给你讲解一下。</p><ul><li><p>MCP Server 就像本地仓库管理员，负责从其他地方拉取需要的货物，每个 MCP Server 负责一类货物。这个货物极可能是从本地调取的，也可能是通过网络远程调取的。MCPServer 是需要通过 MCP 暴露一些特殊能力的轻应用，这就和我们做 HTTP 服务测试时的被测试服务一样，封装了一些逻辑处理能力，通过 HTTP 协议的要求对外提供访问。MCPServer 也是一样的，通过 MCP 协议的封装，提供一些数据、逻辑处理的能力。</p></li><li><p>MCP Client 就是一个能够对接 MCP Server 的“翻译官”，专门负责将协议层的内容转成MCP Host 可以读懂的内容，这就和我们经常打交道的 HTTP Client 一样，在我们开发一个接口测试框架的时候，如果有 Java，那么有 net.http.HttpClient 类支持和 HTTP Server 按照 HTTP 协议进行交互，如果你是 python 技术栈，那么可以选择 requests 库和 HTTPServer 进行交互，这些都是对应技术栈的 HTTP Client，同理 MCP Client 也是一样的。</p></li><li><p>MCP Host 是需要通过 MCP 获得数据的程序，这就像我们做一些 HTTP 协议接口测试的时候大家有时候会用一些测试工具，例如 postman、jmeter 等，这些可以理解成 HTTP 协议的 host，所以 MCP Host 就类似一些可以支持通过内调用自己内部的 MCP Client 访问MCP Server 的程序，例如 Claude Desktop、Cursor、cline（VS Code 插件）、Roo Code（VS Code 插件）或一些 AI 工具。</p></li></ul><p>MCP Server 和 MCP Client 间的传输方式有两种，分别是 STDIO 和 SSE（MCP 协议版本2025-03-26 开始推荐使用 Streamable HTTP 替代 SSE），STDIO 用于本地（Local）资源和服务器的通信，而 SSE（Streamable HTTP）用于远程（Remote）Web API 和当前 MCPHost 的传输。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/2.png" alt=""></a></p><p>MCP 使用了 JSON-RPC 2.0 作为 client 和 server 端的消息传输。JSON-RPC 2.0 是一个用JSON 编码的轻量级远程过程调用协议，它易读、易调试，与编程语言和环境无关，技术成熟，规范清晰且应用广泛等优点，也为 MCP 的广泛应用提供了支持。SON-RPC 2. 定义了request、response、notification 三种类型的消息（例如，图中消息体的例子）。</p><ul><li><p>request 是 client 发给 server 的一个操作请求，消息包含唯一的 id，调用的方法名（例如，tools/call），传给方法的参数（可空）。</p></li><li><p>response 是 server 返回给 client 的消息，消息包含和 request 相同的 id，处理的结果或者错误。</p></li><li><p>notification 是不需要回应的单向信息。通常由服务器发送给客户端，以提供有关事件的更新或通知。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/3.png" alt=""></a></p><p>MCP Servers 通过 MCP Protocol 向 Host Application 提供一些功能列表，例如提供一个工具列表，然后 Host 会将这个列表格式化成一个 LLM 能读懂的格式。Host 可以利用这个功能列表向 LLM 发送一些需要大模型处理的请求（这就是 prompt），LLM 会根据这次的 prompt 返回一个 tool_calls 的 json 字符串。当 Host 接受到这个 tool_calls 后，就会调用对应的 MCPserver 工具返回对应的结果了。</p><h2 id="function-call-和-mcp" tabindex="-1">Function Call 和 MCP <a class="header-anchor" href="#function-call-和-mcp" aria-label="Permalink to &quot;Function Call 和 MCP&quot;">​</a></h2><p>我相信你肯定也听说过 Function Call，这个由 OpenAI 创造出来让大模型能够调用外部函数的能力。那么为什么还要有 MCP 呢？</p><p>Function Calling 是可以用自己的函数当作调用 ChatGPT 的参数，在函数中我们可以做任何事情，例如获取网络上的数据、查询自己的数据库等。白话就是大模型函数调用，不是说去调用大模型函数，而是告诉大模型它需要调用哪些函数完成处理，然后返回结果。</p><p>这么看着和 MCP 感觉差不多，其实两者都是为了解决大模型的两个核心问题而设计的。</p><p>Function Call 是大模型根据上下文自动执行函数的机制，它充当了 AI 模型与外部系统之间的桥梁，但是不同的模型有不同的 Function Calling 实现，代码集成的方式也不一样，这种方式是由不同的 AI 模型平台来定义和实现。</p><p>而 MCP 是一个标准协议，如同电子设备的 Type C 协议（可以充电也可以传输数据），使 AI模型能够与不同的 API 和数据源无缝交互，从而使 AI 系统更可靠，更有效。通过建立通用标准，服务商可以基于协议来推出它们自己服务的 AI 能力，从而支持开发者更快的构建更强大的 AI 应用。开发者也不需要重复造轮子，通过开源项目可以建立强大的 AI 生态。MCP 可以在不同的应用 / 服务之间保持上下文，从而增强整体自主执行任务的能力。</p><h2 id="mcp-的第一个例子" tabindex="-1">MCP 的第一个例子 <a class="header-anchor" href="#mcp-的第一个例子" aria-label="Permalink to &quot;MCP 的第一个例子&quot;">​</a></h2><p>随着 MCP 获得广泛认可，OpenAI 也支持对手公司提出的 MCP 协议了，其实 OpenAI 是有协议指定的先机的，可是机会稍纵即逝，就这么让给了 Anthropic 了。说了这么多，相信你肯定对如何使用 MCP 提起了兴趣，那么下面我就实际带你配置和使用一个简单的本地 MCPServer，让你真正体验一下 MCP 服务的简单和便捷。</p><p>下面的例子使用了 Claude Desktop 作为我们的 MCP Host，配置了一个访问本地文件系统的MCP Server，这个 MCP Server 是本地的服务，因此采用了 STDIO 的方式访问。</p><p>首先打开 Claude Desktop 的 Setting，然后然后选择 Developer 下的 Edit Config。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/4.png" alt=""></a></p><p>打开 claude_desktop_config.json，完成文件系统的 MCP Server 配置。配置如下：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   &quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;/Users/username/Desktop&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;/Users/username/Downloads&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>注意，如上配置中 username 需要替换成自己自己电脑的用户名，同时也需要本地安装node.js 的环境，上面的配置可以让 MCP Server 访问桌面和下载文件夹。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/5.png" alt=""></a></p><p>配置完成后，重启 Cluade Desktop，点击锤子的 icon 就可以看到 MCP Server 提供的工具了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/6.png" alt=""></a></p><p>怎么样，是不是非常简单，那么下面我们看看怎么使用这个 MCP Server。你可以在 ClaudeDesktop 中输入如下 Prompt：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>谁帮我把桌面上的所有图片都移到一个新文件夹里，新的文件夹命名为&quot;picture&quot;。</span></span></code></pre></div><p>当大模型接收到上面的 Prompt 后，大模型判断是否有可以用 MCP Server 提供的工具可以使用，这个时候它刚好读到了我们提供的 MCP Server 有 list_allowed_directories、get_file_info、create_directory 等工具，因此它就利用这些工具完成了你交给它的任务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/7.png" alt=""></a></p><p>在大模型调用工具完成任务过程中，会需要几次获取访问文件系统的权限授权，一定要点击允许，否则它就完不成任务了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E9%87%8D%E5%A1%91%E6%B5%8B%E8%AF%95%E5%BC%80%E5%8F%91%E7%B3%BB%E7%BB%9F%E5%AE%9E%E8%B7%B5/images/05/8.png" alt=""></a></p><p>在允许了对应的操作后，我们就可以看到大模型调用 MCP Server 开始刚工作了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们一起聊了 MCP 协议以及它和 Function Call 的区别，最后我们一起实践了一个 MCPServer 的例子，相信 MCP 的用法简单、配置容易等特点一定给你留下了深刻的印象，MCP将为每一个测试开发工程师打开一个新的大模型赋能测试过程的大门。</p><p>最后希望你能牢记今天的主要内容：</p><ul><li><p>MCP 服务提供了 STDIO 和 SSE（Streamable HTTP）两种模式，这两种模式本地服务STDIO 方式最为有效，网络方式 SSE（Streamable HTTP）模式是最优解。</p></li><li><p>MCP Host 可以是任何一个继承了 MCP Client 的应用，因此你在内部使用的时候一定要物尽其用，尽量充分利用现有的 Host 来解决问题，避免重复开发浪费精力。</p></li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>今天 MCP 最后的例子我推荐你自己亲手试一试，只有动手了才能对 MCP 的有更充分的理解，如果你也完成了如上的 MCP Server 的配置，你都利用它完成了什么样的任务呢？请你在隐藏了关键信息后，将利用大模型和 MCP Server 的过程发到评论区，我是陈磊，我在评论区等你一起交流讨论。</p>`,50)])])}const C=t(n,[["render",l]]);export{B as __pageData,C as default};
